void main() {
  WidgetsFlutterBinding.ensureInitialized();
  runApp(const KelimeSehirApp());
}

class KelimeSehirApp extends StatelessWidget {
  const KelimeSehirApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Kelime Şehirleri',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        useMaterial3: true,
        colorScheme: ColorScheme.fromSeed(seedColor: const Color(0xFFE6C897)),
      ),
      home: const GameScreen(),
    );
  }
}

class WordPosition {
  final String word;
  final int row;
  final int col;
  final bool down;
  const WordPosition(this.word, this.row, this.col, {this.down = false});
}

class PuzzleLevel {
  final String city;
  final String subtitle;
  final String letters;
  final List<WordPosition> answers;
  final List<String> bonusWords;

  const PuzzleLevel({
    required this.city,
    required this.subtitle,
    required this.letters,
    required this.answers,
    required this.bonusWords,
  });

  int get rows => answers.map((a) => a.row + (a.down ? a.word.length : 1))
      .reduce(math.max);
  int get cols => answers.map((a) => a.col + (a.down ? 1 : a.word.length))
      .reduce(math.max);

  Map<String, String> get cells {
    final result = <String, String>{};
    for (final a in answers) {
      for (var i = 0; i < a.word.length; i++) {
        final row = a.row + (a.down ? i : 0);
        final col = a.col + (a.down ? 0 : i);
        final id = '$row:$col';
        final letter = a.word[i];
        assert(!result.containsKey(id) || result[id] == letter,
            'Çakışan kelimeler: $id');
        result[id] = letter;
      }
    }
    return result;
  }

}

