  // Premium arayüz — oyun mekaniği ve kayıt sistemi aynı kalır.
  static const _navy = Color(0xFF0C2440);
  static const _gold = Color(0xFFFFD36E);
  static const _cream = Color(0xFFFFF7E6);

  @override
  Widget build(BuildContext context) {
    final firstCity = _level ~/ 3 == 0;
    return WillPopScope(
      onWillPop: _confirmExit,
      child: Scaffold(
      backgroundColor: _navy,
      body: Stack(
        children: [
          Positioned.fill(
            child: Image.memory(
                firstCity ? _istanbulBackground : _cityBackgrounds[_puzzle.city]!,
                fit: BoxFit.cover, alignment: Alignment.center, gaplessPlayback: true),
          ),
          Positioned.fill(
            child: DecoratedBox(
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                  stops: const [0, .17, .46, .69, 1],
                  colors: [
                    _navy.withOpacity(.76),
                    _navy.withOpacity(.14),
                    _navy.withOpacity(.20),
                    _navy.withOpacity(.18),
                    _navy.withOpacity(.60),
                  ],
                ),
              ),
            ),
          ),
          SafeArea(
            child: LayoutBuilder(builder: (context, viewport) {
              final narrow = viewport.maxWidth < 370;
              final compact = viewport.maxHeight < 730;
              final wheelSize = math.min(
                viewport.maxWidth - (narrow ? 108 : 132),
                compact ? 235.0 : 286.0,
              ).clamp(206.0, 286.0).toDouble();
              final boardMax = compact ? 38.0 : 47.0;
              return Padding(
                padding: EdgeInsets.fromLTRB(narrow ? 10 : 15, 10,
                    narrow ? 10 : 15, 15),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    _premiumTopBar(narrow),
                    SizedBox(height: compact ? 10 : 16),
                    _cityPlaque(),
                    SizedBox(height: compact ? 12 : 18),
                    Expanded(
                      child: Column(
                        children: [
                          Flexible(flex: 9, child: Center(child: _premiumBoard(boardMax))),
                          SizedBox(height: compact ? 8 : 10),
                          _selectionMessage(),
                          SizedBox(height: compact ? 4 : 6),
                          Flexible(flex: 12, child: Center(child: _wheelAndActions(wheelSize, narrow))),
                          SizedBox(height: compact ? 8 : 10),
                          _complete ? _nextButton() : _levelDots(),
                          const SizedBox(height: 10),
                          _premiumBottomBar(),
                        ],
                      ),
                    ),
                  ],
                ),
              );
            }),
          ),
          if (_confettiVisible)
            Positioned.fill(
              child: IgnorePointer(
                child: AnimatedBuilder(
                  animation: _cheerController,
                  builder: (context, child) {
                    final p = _cheerController.value;
                    final opacity = p < .18 ? p / .18 :
                        p > .78 ? (1-p)/.22 : 1.0;
                    return Stack(children: [
                      CustomPaint(
                        size: MediaQuery.sizeOf(context),
                        painter: CelebrationPainter(p),
                      ),
                      Align(
                        alignment: const Alignment(0, -.17),
                        child: Opacity(
                          opacity: opacity.clamp(0, 1).toDouble(),
                          child: Transform.scale(
                            scale: .65 + .4 * Curves.elasticOut.transform(p.clamp(0.0, .9).toDouble()),
                            child: Container(
                              padding: const EdgeInsets.symmetric(horizontal: 21, vertical: 13),
                              decoration: BoxDecoration(
                                color: _navy.withOpacity(.92),
                                border: Border.all(color: _gold,width:2.4),
                                borderRadius: BorderRadius.circular(20),
                                boxShadow: const [BoxShadow(color: Color(0xBB000000),blurRadius: 19)],
                              ),
                              child: Column(mainAxisSize: MainAxisSize.min, children: [
                                const Text('✦  ★  ✦',style: TextStyle(color: _gold,fontSize: 21)),
                                Text(_cheerHeadline,style: const TextStyle(
                                  fontSize: 32,color: _gold,fontFamily: 'serif',fontWeight: FontWeight.w900,
                                  shadows: [Shadow(color: Colors.black,blurRadius: 7)])),
                                Text(_cheerSubline,textAlign: TextAlign.center,
                                  style: const TextStyle(color: Colors.white,fontWeight: FontWeight.bold,fontSize: 12)),
                              ]),
                            ),
                          ),
                        ),
                      ),
                    ]);
                  },
                ),
              ),
            ),
        ],
      ),
    ));
  }

